// «Разобрать апдейт»: turns a Telegram update into one action for the bot.
// Only private chats are answered; anything else produces no items and the run stops.
//
// Actions for everyone: start, calculator, question, retry, news_on, news_off, unknown.
// Extra actions for administrators (Telegram IDs in ADMIN_TELEGRAM_IDS):
//   broadcast_help   — pressed «📣 Рассылка»;
//   broadcast_draft  — sent any other message: it becomes a draft, the bot shows a preview;
//   broadcast_send   — pressed «Отправить» under the preview;
//   broadcast_cancel — pressed «Отмена» under the preview.

const MENU_CALC = '🧮 Калькулятор';
const MENU_ASK = '💬 Задать вопрос';
const MENU_BROADCAST = '📣 Рассылка';

const admins = String($env.ADMIN_TELEGRAM_IDS ?? '')
  .split(/[\s,;]+/)
  .filter(Boolean);

const update = $input.first().json;
let chatId = null;
let chatType = 'private';
let firstName = '';
let callbackId = null;
let action = 'unknown';
let from = null;
let messageId = null; // the user's message, or the message under which a button was pressed
let sourceMessageId = null; // broadcast: the administrator's original message

if (update.callback_query) {
  const cq = update.callback_query;
  chatId = cq.message?.chat?.id ?? cq.from?.id ?? null;
  chatType = cq.message?.chat?.type ?? 'private';
  firstName = cq.from?.first_name ?? '';
  from = cq.from ?? null;
  callbackId = cq.id;
  messageId = cq.message?.message_id ?? null;
  const data = String(cq.data ?? '');
  const isAdmin = admins.includes(String(from?.id));
  if (data === 'retry_calc') action = 'retry';
  else if (data === 'news_on') action = 'news_on';
  else if (data === 'news_off') action = 'news_off';
  else if (isAdmin && /^bc_send:\d+$/.test(data)) {
    action = 'broadcast_send';
    sourceMessageId = Number(data.split(':')[1]);
  } else if (isAdmin && data === 'bc_cancel') action = 'broadcast_cancel';
} else if (update.message) {
  const m = update.message;
  chatId = m.chat?.id ?? null;
  chatType = m.chat?.type ?? 'private';
  firstName = m.from?.first_name ?? '';
  from = m.from ?? null;
  messageId = m.message_id ?? null;
  const isAdmin = admins.includes(String(from?.id));
  const text = (m.text ?? '').trim();
  const cmd = (name) => new RegExp(`^/${name}(\\s|@|$)`).test(text);
  if (cmd('start')) action = 'start';
  else if (text === MENU_CALC || cmd('calc')) action = 'calculator';
  else if (text === MENU_ASK || cmd('ask') || cmd('help')) action = 'question';
  else if (cmd('news')) action = 'news_on';
  else if (cmd('stopnews')) action = 'news_off';
  else if (isAdmin && (text === MENU_BROADCAST || cmd('broadcast'))) action = 'broadcast_help';
  // Any other message from an administrator (text, photo, video, file…) is a broadcast draft.
  else if (isAdmin && !text.startsWith('/') && !m.media_group_id) action = 'broadcast_draft';
  else if (isAdmin && m.media_group_id) action = 'broadcast_album';
}

if (!chatId || chatType !== 'private') return [];

const isAdmin = admins.includes(String(from?.id));

return [
  {
    json: {
      chatId,
      firstName,
      callbackId,
      action,
      isAdmin,
      messageId,
      sourceMessageId,
      // Only these actions show the calculator button, so only they need the availability check.
      needsCheck: ['start', 'calculator', 'retry'].includes(action),
      // Name and username for the bot_users table (language and Premium are not kept).
      user: from
        ? {
            id: from.id,
            username: from.username ?? '',
            first_name: from.first_name ?? '',
            last_name: from.last_name ?? '',
          }
        : null,
    },
  },
];

// «Собрать ответ»: decides what the bot sends. Each output item is one Bot API call
// ({ method, payload }); the next node sends them in order.
// Links and texts come from environment variables set in docker-compose (.env).

const MENU_CALC = '🧮 Калькулятор';
const MENU_ASK = '💬 Задать вопрос';
const MENU_BROADCAST = '📣 Рассылка';

const p = $('Разобрать апдейт').first().json;
const calcUrl = $env.CALCULATOR_URL;
const policyUrl = $env.PD_POLICY_URL;
const consentUrl = $env.PD_CONSENT_URL;
const specialistUrl = $env.SPECIALIST_URL;
const mailingConsentUrl = $env.PD_MAILING_CONSENT_URL;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// The calculator counts as available only if its page answered 2xx and is really our app.
let available = false;
if (p.needsCheck) {
  const r = $input.first().json;
  const body = typeof r.body === 'string' ? r.body : typeof r.data === 'string' ? r.data : '';
  available = !r.error && r.statusCode >= 200 && r.statusCode < 300 && body.includes('sovest-mortgage-calculator');
}

// Administrators get one more menu button for broadcasts.
const menuKeyboard = {
  keyboard: [[{ text: MENU_CALC }, { text: MENU_ASK }], ...(p.isAdmin ? [[{ text: MENU_BROADCAST }]] : [])],
  resize_keyboard: true,
  is_persistent: true,
};
const calcButton = { inline_keyboard: [[{ text: '🧮 Открыть калькулятор', web_app: { url: calcUrl } }]] };
const retryButton = { inline_keyboard: [[{ text: '🔄 Повторить', callback_data: 'retry_calc' }]] };

const send = (text, reply_markup) => ({
  json: {
    method: 'sendMessage',
    payload: { chat_id: p.chatId, text, parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup },
  },
});

// Same buttons are used by «Подписка на новости» and «Рассылка» branches of the workflow.
const newsButton = { inline_keyboard: [[{ text: '🔔 Получать новости', callback_data: 'news_on' }]] };
const removeButtons = () => ({
  json: {
    method: 'editMessageReplyMarkup',
    payload: { chat_id: p.chatId, message_id: p.messageId, reply_markup: { inline_keyboard: [] } },
  },
});

const newsPrompt =
  'Прежде чем продолжим, один важный момент\n\n' +
  'Я буду присылать в этот бот полезные материалы, если хотите получать – нажмите кнопку под этим сообщением👇 ' +
  'Никакого спама, согласие нужно по требованиям законодательства РФ.\n\n' +
  'Нажимая на кнопку, вы подтверждаете, что ' +
  `<a href="${esc(mailingConsentUrl)}">согласны получать информационные и рекламные рассылки</a>`;

const unavailable = () =>
  send(
    'Калькулятор сейчас не открывается — похоже, на сервере неполадки.\n\n' +
      'Попробуйте ещё раз через пару минут: нажмите «Повторить».',
    retryButton,
  );

const welcomeText =
  `Здравствуйте${p.firstName ? `, ${esc(p.firstName)}` : ''}! 👋\n\n` +
  'Это ипотечный калькулятор центра недвижимости «Совесть». ' +
  'Он покажет ежемесячный платёж, переплату и то, как досрочные погашения сокращают срок и проценты.\n\n' +
  '⚠️ <b>Калькулятор носит ознакомительный характер.</b> Расчёт не является публичной офертой; ' +
  'точные условия кредита определяет банк.\n\n' +
  'Пользуясь ботом, вы соглашаетесь с ' +
  `<a href="${esc(policyUrl)}">политикой обработки персональных данных</a> и даёте ` +
  `<a href="${esc(consentUrl)}">согласие на обработку персональных данных</a>.`;

const out = [];

if (p.callbackId) {
  // Stops the loading spinner on the pressed inline button.
  out.push({ json: { method: 'answerCallbackQuery', payload: { callback_query_id: p.callbackId } } });
}

switch (p.action) {
  case 'start':
    if (available) {
      // A message carries either buttons under it or the bottom menu. The welcome has the calculator button,
      // the bottom menu comes with the next reply (e.g. «Готово, вы подписаны»); commands are in the «Меню» button.
      out.push(send(welcomeText, calcButton));
    } else {
      out.push(send(welcomeText, menuKeyboard));
      out.push(unavailable());
    }
    out.push(send(newsPrompt, newsButton));
    break;
  case 'news_on':
    if (p.callbackId) out.push(removeButtons());
    out.push(
      send(
        'Готово, вы подписаны на новости 🔔\n\n' +
          'Отписаться можно в любой момент: кнопкой под любой рассылкой или командой /stopnews.',
        menuKeyboard,
      ),
    );
    break;
  case 'news_off':
    if (p.callbackId) out.push(removeButtons());
    out.push(
      send(
        'Вы отписались от новостей — больше присылать их не будем.\n\nПодписаться снова: команда /news.',
        menuKeyboard,
      ),
    );
    break;
  case 'broadcast_help':
    out.push(
      send(
        '📣 <b>Рассылка подписчикам</b>\n\n' +
          'Пришлите сюда сообщение так, как его должны увидеть подписчики: текст, фото или видео с подписью, файл. ' +
          'Форматирование и ссылки сохранятся.\n\n' +
          'Бот покажет предпросмотр с кнопками «Отправить» и «Отмена». До нажатия «Отправить» никто ничего не получит.',
        menuKeyboard,
      ),
    );
    break;
  case 'broadcast_album':
    out.push(send('Альбом из нескольких фото разослать не получится. Пришлите одно фото или видео с подписью.'));
    break;
  case 'broadcast_draft':
    out.push(send('Предпросмотр 👇 Так рассылку увидят подписчики. Проверьте и нажмите «Отправить».'));
    out.push({
      json: {
        method: 'copyMessage',
        payload: {
          chat_id: p.chatId,
          from_chat_id: p.chatId,
          message_id: p.messageId,
          reply_markup: {
            inline_keyboard: [
              [
                { text: '✅ Отправить подписчикам', callback_data: `bc_send:${p.messageId}` },
                { text: 'Отмена', callback_data: 'bc_cancel' },
              ],
            ],
          },
        },
      },
    });
    break;
  case 'broadcast_cancel':
    out.push(removeButtons());
    out.push(send('Рассылка отменена.'));
    break;
  case 'broadcast_send':
    // The sending itself runs in the «Рассылка» branch; here only the buttons go away.
    out.push(removeButtons());
    out.push(send('Отправляю рассылку… Когда закончу, пришлю отчёт.'));
    break;
  case 'calculator':
  case 'retry':
    out.push(available ? send('Откройте калькулятор по кнопке ниже:', calcButton) : unavailable());
    break;
  case 'question':
    out.push(
      send(
        'Ответим на вопросы об ипотеке, объектах и сделке. Напишите нашему специалисту — он ответит в личных сообщениях.',
        { inline_keyboard: [[{ text: '✉️ Написать специалисту', url: specialistUrl }]] },
      ),
    );
    break;
  default:
    out.push(send('Выберите действие в меню ниже 👇', menuKeyboard));
}

return out;

// «Карточка пользователя»: one bot_users row per Telegram user, refreshed on every message.
// Only what Telegram itself sends with an update; phone numbers are not requested.
// The table's own createdAt column = first visit, updatedAt = last activity.

const p = $('Разобрать апдейт').first().json;
const u = p.user;
if (!u || !u.id) return [];

const clip = (s, n) => String(s ?? '').slice(0, n);

return [
  {
    json: {
      telegram_id: String(u.id),
      username: clip(u.username, 64),
      profile_link: u.username ? `https://t.me/${clip(u.username, 64)}` : '',
      first_name: clip(u.first_name, 128),
      last_name: clip(u.last_name, 128),
      last_action: p.action,
      last_seen_at: new Date().toISOString(),
    },
  },
];

// «Подписка: строка»: one news_subscribers row per Telegram user.
// news_on  — the user pressed «🔔 Получать новости» (or /news): this is the consent to mailings, its time is kept;
// news_off — the user unsubscribed (button under a broadcast or /stopnews).

const p = $('Разобрать апдейт').first().json;
const u = p.user;
if (!u || !u.id) return [];

const clip = (s, n) => String(s ?? '').slice(0, n);
const now = new Date().toISOString();

const row = {
  telegram_id: String(u.id),
  username: clip(u.username, 64),
  first_name: clip(u.first_name, 128),
  subscribed: p.action === 'news_on',
};
if (p.action === 'news_on') row.subscribed_at = now;
else {
  row.unsubscribed_at = now;
  row.unsubscribe_reason = 'user';
}

return [{ json: row }];

// «Кому отправить»: one Bot API copyMessage call per subscriber.
// The administrator's original message is copied as is (text, photo, formatting),
// with an «Отписаться» button under it.

const p = $('Разобрать апдейт').first().json;
const unsubscribe = { inline_keyboard: [[{ text: '🔕 Отписаться от новостей', callback_data: 'news_off' }]] };

const ids = [
  ...new Set(
    $input
      .all()
      .map((i) => i.json)
      .filter((r) => r.telegram_id && r.subscribed === true)
      .map((r) => String(r.telegram_id)),
  ),
];

// No subscribers: one empty item, so the report still goes out.
if (ids.length === 0) return [{ json: { none: true } }];

return ids.map((id) => ({
  json: {
    telegram_id: id,
    payload: { chat_id: id, from_chat_id: p.chatId, message_id: p.sourceMessageId, reply_markup: unsubscribe },
  },
}));

// «Итоги рассылки»: counts deliveries, finds people who blocked the bot, prepares the report.
// Telegram answers 403 when the user blocked the bot or deleted the account: they are unsubscribed.

const p = $('Разобрать апдейт').first().json;
const targets = $('Кому отправить').all().map((i) => i.json);
const results = $('Разослать').isExecuted ? $('Разослать').all().map((i) => i.json) : [];

let delivered = 0;
const blocked = [];
const failed = [];
targets.forEach((t, i) => {
  if (t.none) return;
  const r = results[i] ?? {};
  const body = typeof r.body === 'object' && r.body ? r.body : {};
  if (r.statusCode === 200 && body.ok) delivered += 1;
  else if (r.statusCode === 403) blocked.push(t.telegram_id);
  else failed.push(`${t.telegram_id}: ${body.description ?? r.statusCode ?? r.error?.message ?? 'нет ответа'}`);
});
const total = targets.filter((t) => !t.none).length;

let text;
if (total === 0) {
  text = 'Подписчиков пока нет — рассылка никому не отправлена.';
} else {
  text = `📣 Рассылка отправлена\n\nПодписчиков: ${total}\nДоставлено: ${delivered}`;
  if (blocked.length) text += `\nЗаблокировали бота: ${blocked.length} (они отписаны)`;
  if (failed.length) text += `\nНе доставлено по другим причинам: ${failed.length}`;
}

return [
  {
    json: {
      report: { chat_id: p.chatId, text },
      log: {
        source_message_id: String(p.sourceMessageId),
        recipients: total,
        delivered,
        blocked: blocked.length,
        failed: failed.length,
        errors: failed.slice(0, 20).join('\n'),
        finished_at: new Date().toISOString(),
      },
      blocked,
    },
  },
];

const now = new Date().toISOString();
return $('Итоги рассылки').first().json.blocked.map((id) => ({
  json: { telegram_id: id, subscribed: false, unsubscribed_at: now, unsubscribe_reason: 'blocked' },
}));

// «Проверить подпись Telegram»: validates Mini App initData (HMAC-SHA256 with the bot token,
// https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app)
// and turns the calculation into one Data Table row keyed by the Telegram user ID.
// The user ID is taken only from the signed initData, never from the request body.

const crypto = require('crypto');

const MAX_AGE_SECONDS = 24 * 60 * 60;
const NUMBER_FIELDS = [
  'price',
  'down_payment',
  'loan_amount',
  'term_months',
  'rate',
  'monthly_payment',
  'total_interest',
  'overpayment_pct',
  'total_paid',
  'actual_term_months',
  'prepaid_total',
  'saved_interest',
];
const STRING_FIELDS = ['start_month', 'prepayments', 'last_payment_month'];

const fail = (status, error) => [{ json: { valid: false, status, error } }];

const body = $input.first().json.body ?? {};
const token = $env.TELEGRAM_BOT_TOKEN;
if (!token) return fail(500, 'bot_token_not_configured');
if (typeof body.initData !== 'string' || !body.calculation || typeof body.calculation !== 'object') {
  return fail(400, 'bad_request');
}

// 1. Signature. (URLSearchParams is not available in the Code-node sandbox, so parse by hand.)
const decode = (s) => {
  try {
    return decodeURIComponent(s.replace(/\+/g, ' '));
  } catch {
    return null;
  }
};
const params = new Map();
for (const part of body.initData.split('&')) {
  if (!part) continue;
  const eq = part.indexOf('=');
  const key = decode(eq < 0 ? part : part.slice(0, eq));
  const value = decode(eq < 0 ? '' : part.slice(eq + 1));
  if (key === null || value === null) return fail(401, 'bad_init_data');
  params.set(key, value);
}
const hash = params.get('hash');
if (!hash) return fail(401, 'no_signature');
params.delete('hash');
const dataCheckString = [...params.entries()]
  .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  .map(([k, v]) => `${k}=${v}`)
  .join('\n');
const secret = crypto.createHmac('sha256', 'WebAppData').update(token).digest();
const expected = crypto.createHmac('sha256', secret).update(dataCheckString).digest('hex');
if (expected.length !== hash.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(hash))) {
  return fail(401, 'bad_signature');
}

// 2. Freshness: initData older than a day is refused.
const authDate = Number(params.get('auth_date'));
if (!Number.isFinite(authDate) || Date.now() / 1000 - authDate > MAX_AGE_SECONDS) return fail(401, 'expired');

// 3. User.
let user;
try {
  user = JSON.parse(params.get('user') ?? '');
} catch {
  return fail(401, 'no_user');
}
if (!user || !user.id) return fail(401, 'no_user');

// 4. Calculation.
const c = body.calculation;
const row = {
  telegram_id: String(user.id),
  username: String(user.username ?? '').slice(0, 64),
  first_name: String(user.first_name ?? '').slice(0, 128),
  last_name: String(user.last_name ?? '').slice(0, 128),
};
for (const k of NUMBER_FIELDS) {
  const v = Number(c[k]);
  if (!Number.isFinite(v) || v < 0 || v > 1e12) return fail(400, `bad_field_${k}`);
  row[k] = v;
}
for (const k of STRING_FIELDS) {
  if (typeof c[k] !== 'string') return fail(400, `bad_field_${k}`);
  row[k] = c[k].slice(0, 2000);
}
row.saved_at = new Date().toISOString();

return [{ json: { valid: true, row } }];
